<?php
namespace App\Http\Controllers\Management;use App\Http\Controllers\Controller;use App\Models\{HmsPermission,User};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class PermissionsController extends Controller{public function index(Request $r){abort_unless(in_array($r->user()->role,['super_admin','hotel_owner','general_manager'],true),403);$users=User::when($r->user()->role!=='super_admin',fn($q)=>$q->where('property_id',$r->user()->property_id))->orderBy('name')->get();return view('management.permissions',['permissions'=>HmsPermission::orderBy('module')->orderBy('label')->get(),'users'=>$users]);}public function role(Request $r){abort_unless(in_array($r->user()->role,['super_admin','hotel_owner','general_manager'],true),403);$d=$r->validate(['role'=>'required|string','permission_ids'=>'array']);DB::table('hms_role_permissions')->where('role',$d['role'])->delete();foreach($d['permission_ids']??[] as $id)DB::table('hms_role_permissions')->insert(['role'=>$d['role'],'permission_id'=>$id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Role permissions updated.');}}
